import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { ProjectRowActions } from '../../slots/defs/projectRowActions';
import type { Project } from './ProjectsPage';

// The button that deletes a project the user no longer needs — its own file, filling the
// project-row-actions slot. Deleting is a useMutation that POSTs the id to /api/projects/remove;
// on success it invalidates ['projects'] so the list (and anything else showing projects) refetches
// and the row drops out — the list is never edited to know about this action. Carries
// data-testid="project-delete-<id>" (the test contract).
export const contribution = ProjectRowActions.fill({
  order: 20,
  Component: ({ projectId }) => {
    const queryClient = useQueryClient();
    const remove = useMutation({
      mutationFn: () => postJson<Project>('/api/projects/remove', { id: projectId }),
      onSuccess: () => {
        void queryClient.invalidateQueries({ queryKey: ['projects'] });
      },
    });
    return (
      <button
        type="button"
        data-testid={`project-delete-${projectId}`}
        disabled={remove.isPending}
        onClick={() => remove.mutate()}
      >
        Delete
      </button>
    );
  },
});

import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import type { Project } from './ProjectsPage';

// A client's projects: the projects listing scoped to one client, rendered in the client-detail
// context. Server data is read with useQuery under the SAME ['projects'] key the projects page owns
// (so a project write that invalidates ['projects'] refreshes this too) and filtered to the client
// it is handed — never copied into state, never hand-maintained (rule 5). Reuses the
// project-row-<id>/project-name anchors inside its own client-projects-table.
export function ClientProjectsPanel({ clientId }: { clientId: number }) {
  const projects = useQuery({
    queryKey: ['projects'],
    queryFn: () => getJson<Project[]>('/api/projects'),
  });

  const rows = (projects.data ?? []).filter((p) => p.clientId === clientId);

  return (
    <section data-testid="client-projects">
      {rows.length === 0 ? (
        <p data-testid="client-projects-empty">No projects yet.</p>
      ) : (
        <table data-testid="client-projects-table">
          <thead>
            <tr>
              <th>Name</th>
            </tr>
          </thead>
          <tbody>
            {rows.map((p) => (
              <tr key={p.id} data-testid={`project-row-${p.id}`}>
                <td data-testid="project-name">{p.name}</td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
    </section>
  );
}

